import apiClient from './apiClient';

const query = (type, academicYear) =>
  `type=${encodeURIComponent(type)}&academicYear=${encodeURIComponent(academicYear)}`;

export const reportApi = {
  /** Preview data for the authenticated faculty member. */
  getReportPreview: (reportType, academicYear) =>
    apiClient.get(`/reports/preview?${query(reportType, academicYear)}`),

  /** PDF is generated by the Flask backend; the frontend only downloads it. */
  downloadReportPdf: (reportType, academicYear) =>
    apiClient.download(`/reports/download?${query(reportType, academicYear)}`),

  /** Institution-wide reports (admin). */
  getInstitutionReportPreview: (reportType, academicYear) =>
    apiClient.get(`/admin/reports/preview?${query(reportType, academicYear)}`),

  downloadInstitutionReportPdf: (reportType, academicYear) =>
    apiClient.download(`/admin/reports/download?${query(reportType, academicYear)}`),
};

export default reportApi;
